card[data-size=\"3x3\"] .su,.card[data-size=\"3x3\"] .sl2{display:none}\n.card[data-size=\"6x3\"] .h-v{font-size:20px}\n.card[data-size=\"6x6\"] .head{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;align-items:stretch}\n.card[data-size=\"6x6\"] .stats{display:contents}\n.card[data-size=\"6x6\"] .h-main,.card[data-size=\"6x6\"] .stat{border:1px solid var(--line);border-radius:12px;padding:7px 9px;background:var(--paper);align-content:center}\n.card[data-size=\"6x6\"] .h-v{font-size:17px}\n.card[data-size=\"6x6\"] .stat{flex-wrap:wrap;gap:1px 8px}\n.card[data-size=\"6x6\"] .stat .sl{flex:1 0 100%;color:var(--muted);font-size:11px;font-weight:400}\n.card[data-size=\"6x6\"] .stat.od.on .sl{font-weight:600;color:var(--ink)}\n.card[data-size=\"6x6\"] .stat.od.on{border-color:#C2410C}\n.card[data-size=\"6x6\"] .sv{order:1;font-size:17px;font-weight:700}\n.card[data-size=\"6x6\"] .sn{order:2}\n\n.body{grid-area:body;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.chips{flex:none;display:flex;gap:4px;overflow-x:auto;padding-bottom:2px}\n.fc{flex:none;border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:99px;padding:3px 9px;font-size:11px;cursor:pointer;white-space:nowrap}\n.fc[aria-pressed=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.list{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;overflow-y:auto;overflow-x:hidden}\n.empty{margin:auto;text-align:center;color:var(--muted);font-size:12px;padding:10px 6px}\n.empty.sm{padding:6px 0;text-align:left;margin:0}\n\n.row{flex:none;min-width:0;display:grid;gap:3px;padding:7px 9px;border:1px solid var(--line);border-left:3px solid var(--line);border-radius:10px;background:var(--paper);cursor:pointer}\n.row:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.row.st-overdue{border-left-color:#C2410C}\n.row.st-soon{border-left-color:var(--accent)}\n.row.st-paid .r-left{color:var(--muted)}\n.r-top{display:flex;align-items:center;gap:6px;min-width:0}\n.r-name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px}\n.proj{color:var(--muted)}\n.chip{flex:none;font-size:10.5px;line-height:1.5;padding:0 7px;border-radius:99px;border:1px solid var(--line);white-space:nowrap;background:transparent}\n.chip.overdue{border-color:#C2410C;background:color-mix(in srgb,#C2410C 16%,transparent);font-weight:650}\n.chip.soon{border-color:var(--accent);background:var(--soft)}\n.chip.paid{background:var(--soft);color:var(--muted)}\n.r-mid{display:flex;align-items:baseline;justify-content:space-between;gap:6px;min-width:0}\n.r-left{font-weight:700;white-space:nowrap}\n.r-due{flex:1;text-align:right;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:11px}\n.r-pay{display:none;flex:none;border:1px solid var(--accent);background:transparent;color:var(--ink);border-radius:99px;padding:0 8px;font-size:11px;cursor:pointer}\n.card[data-size=\"6x6\"] .r-pay{display:inline-block}\n.r-sub{display:flex;justify-content:space-between;gap:6px;font-size:11px;color:var(--muted);min-width:0}\n.r-got{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.inv{flex:none;white-space:nowrap}\n.inv.on{color:var(--ink)}\n.bar{height:3px;background:var(--line);border-radius:2px;overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:2px}\n.bar.big{height:6px;border-radius:3px}\n.card[data-size=\"3x3\"] .r-sub,.card[data-size=\"3x3\"] .pre,.card[data-size=\"6x3\"] .bar{display:none}\n.card[data-size=\"3x3\"] .row{padding:6px 8px}\n\n.add{grid-area:add;display:flex;align-items:center;justify-content:center;gap:6px;border:0;background:var(--accent);color:var(--on-accent);border-radius:10px;padding:9px 12px;font-size:13px;font-weight:650;cursor:pointer}\n.card[data-size=\"3x3\"] .add{width:34px;height:34px;padding:0;align-self:start}\n.card[data-size=\"3x3\"] .bt{display:none}\n.plus{font-size:16px;line-height:1}\n\n.sh{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto}\n.card[data-size=\"3x3\"] .sh,.card[data-size=\"6x3\"] .sh{padding:10px;gap:6px}\n.card[data-size=\"6x6\"] .sh{padding:14px;gap:10px}\n.s-head{display:flex;align-items:center;gap:8px;min-width:0}\n.s-title{flex:1;min-width:0;display:grid}\n.s-title b{font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.s-title span{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.back{flex:none;width:28px;height:28px;border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:8px;font-size:17px;line-height:1;cursor:pointer}\n.s-body{min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:grid;gap:10px;align-content:start;padding-right:2px}\n.dcol{display:grid;gap:8px;align-content:start;min-width:0}\n.card[data-size=\"6x3\"] .det{grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start}\n.s-foot{display:grid;gap:5px;min-width:0}\n.f-btns{display:flex;gap:8px}\n.f-btns .btn{flex:1}\n\n.btn{border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:10px;padding:8px 12px;font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.danger{border-color:#C2410C;background:color-mix(in srgb,#C2410C 14%,transparent)}\n.btn.sm{padding:4px 10px;font-size:12px;border-radius:8px}\n.btn.del{justify-self:start;color:var(--muted);font-weight:500}\n.card[data-size=\"3x3\"] .btn,.card[data-size=\"6x3\"] .btn{padding:6px 10px}\n.card[data-size=\"3x3\"] .btn.sm,.card[data-size=\"6x3\"] .btn.sm{padding:3px 9px}\n.back:focus-visible,.btn:focus-visible,.fc:focus-visible,.add:focus-visible,.tog:focus-visible,.lk:focus-visible,.in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.d-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.due{font-size:12px;color:var(--muted)}\n.figs{display:grid;gap:4px}\n.fig{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.fl{font-size:11.5px;color:var(--muted)}\n.fv{font-weight:700;white-space:nowrap}\n.card[data-size=\"6x3\"] .figs,.card[data-size=\"6x6\"] .figs{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.card[data-size=\"6x3\"] .fig,.card[data-size=\"6x6\"] .fig{flex-direction:column;align-items:flex-start;gap:1px;border:1px solid var(--line);border-radius:10px;padding:5px 8px;background:var(--paper)}\n.kv{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.tog{flex:none;border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:99px;padding:3px 11px;font-size:12px;cursor:pointer;white-space:nowrap}\n.tog.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.sec{font-size:12px;font-weight:700;color:var(--ink);padding-top:2px}\n.pays{display:grid;gap:6px}\n.pay{display:grid;gap:2px;padding:6px 9px;border:1px solid var(--line);border-radius:10px;background:var(--paper);min-width:0}\n.p1{display:flex;justify-content:space-between;gap:8px;font-weight:650}\n.pa{white-space:nowrap}\n.p2{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;color:var(--muted);min-width:0}\n.note{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.acts{flex:none;display:flex;gap:2px}\n.lk{border:0;background:transparent;color:var(--ink);text-decoration:underline;font-size:11.5px;padding:3px 5px;cursor:pointer;white-space:nowrap}\n.lk.strong{font-weight:700}\n.dz{display:grid;gap:6px;font-size:12px;padding:8px;border:1px solid #C2410C;border-radius:10px}\n\n.form{gap:8px}\n.card[data-size=\"6x3\"] .form,.card[data-size=\"6x6\"] .form{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 12px}\n.full{grid-column:1/-1}\n.fld{display:grid;gap:3px;min-width:0;align-content:start}\n.in{width:100%;min-width:0;padding:7px 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font-size:13px}\n.card[data-size=\"3x3\"] .in,.card[data-size=\"6x3\"] .in{padding:5px 7px}\n.hint{font-size:11px;color:var(--muted)}\n.fillall{justify-self:start;padding-left:0}\n.err{font-size:11.5px;line-height:1.35;padding:2px 7px;border-left:3px solid #C2410C;color:var(--ink)}\n";
var RANK={overdue:0,soon:1,pending:2,paid:3};
function dn(s){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');if(!m)return null;return Math.floor(Date.UTC(+m[1],+m[2]-1,+m[3])/86400000);}
function toC(v){var n=Number(v);return Number.isFinite(n)?Math.round(n*100):0;}
function yuan(c){
  var neg=c<0,a=Math.abs(c),i=Math.floor(a/100),f=a%100;
  var s=String(i).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  if(f)s+='.'+(f<10?'0':'')+f;
  return (neg?'-':'')+'¥'+s;
}
function fd(s,today){
  var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');
  if(!m)return s||'';
  var y=(today||'').slice(0,4);
  return (m[1]===y?'':m[1]+'年')+(+m[2])+'月'+(+m[3])+'日';
}
function itemsOf(s){return s&&Array.isArray(s.items)?s.items:[];}
function calc(it,today){
  var pays=Array.isArray(it.payments)?it.payments:[];
  var rc=0;
  pays.forEach(function(p){rc+=toC(p.amount);});
  var am=toC(it.amount),dd=dn(it.due),td=dn(today);
  var diff=(dd==null||td==null)?null:dd-td;
  var paid=am>0&&rc>=am;
  var st=paid?'paid':(diff!=null&&diff<0?'overdue':(diff!=null&&diff<=7?'soon':'pending'));
  return {it:it,pays:pays,rc:rc,am:am,left:Math.max(am-rc,0),over:Math.max(rc-am,0),paid:paid,diff:diff,st:st,pct:am>0?Math.min(100,Math.round(rc*100/am)):0};
}
function lastPay(x){
  var d='';
  x.pays.forEach(function(p){if((p.date||'')>d)d=p.date||'';});
  return d;
}
function sortInfos(list){
  var a=list.map(function(x,i){x.i=i;return x;});
  a.sort(function(p,q){
    var r=RANK[p.st]-RANK[q.st];
    if(r)return r;
    if(p.st==='paid'){
      var lp=lastPay(p),lq=lastPay(q);
      if(lp!==lq)return lp<lq?1:-1;
      return p.i-q.i;
    }
    var dp=p.diff==null?1e9:p.diff,dq=q.diff==null?1e9:q.diff;
    if(dp!==dq)return dp-dq;
    return p.i-q.i;
  });
  return a;
}
function chipOf(x){
  if(x.st==='paid')return {k:'paid',t:'✓ 已收齐'};
  if(x.st==='overdue')return {k:'overdue',t:'逾期 '+(-x.diff)+' 天'};
  if(x.st==='soon')return {k:'soon',t:x.diff===0?'今天到期':x.diff+' 天后到期'};
  return {k:'pending',t:x.diff==null?'未设到期日':'未到期'};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const today=day();
  const sz=size||root.getAttribute('data-size')||'3x3';
  const post=[];
  if(!ui.sc)ui.sc={};
  if(!ui.filter)ui.filter='all';

  function E(tag,attrs,...kids){
    return el(tag,attrs||{},...kids.filter(k=>k!=null&&k!==false));
  }
  function A(n,o){
    Object.keys(o).forEach(k=>n.setAttribute(k,o[k]));
    return n;
  }
  function nu(view,sel,extra){
    const sc=view==='list'?(ui.sc||{}):{list:(ui.sc&&ui.sc.list)||0};
    return Object.assign({},ui,{view:view,sel:sel==null?null:sel,err:'',busy:false,cdel:false,cpay:null,draft:null,payId:null,sc:sc},extra||{});
  }
  function go(view,sel,extra){
    Object.assign(ui,nu(view,sel,extra));
    redraw();
  }
  function scr(node,key){
    node.addEventListener('scroll',()=>{ui.sc[key]=node.scrollTop;});
    post.push(()=>{const v=ui.sc[key];if(v)node.scrollTop=v;});
    return node;
  }
  function draftOf(it){
    if(!it)return {client:'',project:'',amount:'',due:'',invoiced:false,pay:'',payDate:today};
    return {client:it.client||'',project:it.project||'',amount:String(toC(it.amount)/100),due:it.due||'',invoiced:!!it.invoiced};
  }
  function fail(m){ui.err=m;ui.busy=false;redraw();}
  function track(p){
    Promise.resolve(p).then(ok=>{if(ok===false)ui.busy=false;},()=>{ui.busy=false;ui.err='保存失败，请重试';redraw();});
  }

  function field(label,key,o){
    o=o||{};
    const d=ui.draft;
    const n=E('input',{class:'in',oninput:()=>{d[key]=n.value;},onchange:()=>{d[key]=n.value;},onkeydown:e=>{if(e.key==='Enter'&&o.enter){e.preventDefault();o.enter();}}});
    n.type=o.type||'text';
    if(o.ph)n.placeholder=o.ph;
    if(o.type==='number'){n.step='any';n.min='0';n.inputMode='decimal';}
    n.value=d[key]==null?'':d[key];
    const lab=E('label',{class:'fld'+(o.full?' full':'')},E('span',{class:'fl'},label+(o.req?' *':'')),n);
    lab.input=n;
    return lab;
  }
  function togField(label,key){
    const d=ui.draft;
    const t=E('button',{class:'tog',type:'button'});
    const paint=()=>{
      t.classList.toggle('on',!!d[key]);
      t.setAttribute('aria-pressed',String(!!d[key]));
      t.textContent=d[key]?'✓ 已开票':'未开票';
    };
    t.addEventListener('click',()=>{d[key]=!d[key];paint();});
    paint();
    return E('div',{class:'fld'},E('span',{class:'fl'},label),t);
  }

  function saveRecord(){
    if(ui.busy)return;
    const d=ui.draft,id=ui.sel;
    const client=String(d.client||'').trim(),project=String(d.project||'').trim();
    if(!client)return fail('请填写客户名称');
    const am=toC(d.amount);
    if(!(Number(d.amount)>0)||am<=0)return fail('约定金额要大于 0');
    if(!dn(d.due))return fail('请选择约定到账日');
    let pc=0;
    if(!id&&String(d.pay||'').trim()!==''){
      pc=toC(d.pay);
      if(!(Number(d.pay)>0)||pc<=0)return fail('已收金额要大于 0；还没收到就留空');
      if(!dn(d.payDate))return fail('请选择这笔已收款的日期');
    }
    const rec={client:client,project:project,amount:am/100,due:d.due,invoiced:!!d.invoiced};
    const nid=id?null:uid(),pid=pc?uid():null,pdate=d.payDate;
    ui.busy=true;
    track(commit(s=>{
      const arr=itemsOf(s);
      if(id)return Object.assign({},s,{items:arr.map(i=>i.id===id?Object.assign({},i,rec):i)});
      const pays=pc?[{id:pid,date:pdate,amount:pc/100,note:''}]:[];
      return Object.assign({},s,{items:arr.concat([Object.assign({id:nid,payments:pays,created:today},rec)])});
    },id?nu('detail',id):nu('list')));
  }
  function savePay(){
    if(ui.busy)return;
    const d=ui.draft,id=ui.sel,pid0=ui.payId;
    const c=toC(d.amount);
    if(!(Number(d.amount)>0)||c<=0)return fail('收款金额要大于 0');
    if(!dn(d.date))return fail('请选择收款日期');
    const pay={date:d.date,amount:c/100,note:String(d.note||'').trim()};
    const npid=pid0?null:uid();
    ui.busy=true;
    track(commit(s=>Object.assign({},s,{items:itemsOf(s).map(i=>{
      if(i.id!==id)return i;
      const ps=Array.isArray(i.payments)?i.payments:[];
      return Object.assign({},i,{payments:pid0?ps.map(p=>p.id===pid0?Object.assign({},p,pay):p):ps.concat([Object.assign({id:npid},pay)])});
    })}),nu('detail',id)));
  }
  function delPay(id,pid){
    ui.cpay=null;
    update(s=>Object.assign({},s,{items:itemsOf(s).map(i=>i.id!==id?i:Object.assign({},i,{payments:(Array.isArray(i.payments)?i.payments:[]).filter(p=>p.id!==pid)}))})).catch(()=>{});
  }
  function delItem(id){
    if(ui.busy)return;
    ui.busy=true;
    track(commit(s=>Object.assign({},s,{items:itemsOf(s).filter(i=>i.id!==id)}),nu('list')));
  }
  function setInv(id,v){
    update(s=>Object.assign({},s,{items:itemsOf(s).map(i=>i.id===id?Object.assign({},i,{invoiced:v}):i)})).catch(()=>{});
  }


  function stat(cls,l1,l2,arr){
    const sum=arr.reduce((a,x)=>a+x.left,0);
    return E('div',{class:'stat '+cls+(arr.length?' on':'')},
      E('span',{class:'sl'},l1,E('span',{class:'sl2'},l2)),
      E('span',{class:'sn'},String(arr.length),E('span',{class:'su'},' 笔')),
      E('span',{class:'sv'},yuan(sum)));
  }
  function openRow(id){go('detail',id);}
  function row(x){
    const it=x.it,c=chipOf(x);
    const bar=E('i');
    bar.style.width=x.pct+'%';
    const n=E('div',{class:'row st-'+x.st},
      E('div',{class:'r-top'},
        E('div',{class:'r-name'},E('b',{},it.client||'未命名客户'),it.project?E('span',{class:'proj'},' · '+it.project):null),
        E('span',{class:'chip '+c.k},c.t)),
